<div class="d-flex flex-wrap justify-content-between align-items-end mb-4 gap-3"><div><div class="eyebrow">The archive</div><h1 class="fw-bold mb-0">Photo Gallery</h1></div><div class="btn-group" role="group"><button class="btn btn-outline-dark active" data-grid="3">3 Columns</button><button class="btn btn-outline-dark" data-grid="4">4 Columns</button><button class="btn btn-outline-dark" data-grid="list">List View</button></div></div><?php if(!$photos): ?><div class="panel p-5 text-center"><h2 class="h4">No photos yet</h2><p class="text-secondary">Be the first person to share a memory.</p><?php if(currentUser()): ?><a href="<?= baseUrl('photo/create') ?>" class="btn btn-dark">Upload a photo</a><?php endif; ?></div><?php else: ?><div id="gallery" class="row g-4 gallery-grid"><?php foreach($photos as $photo): ?><div class="gallery-item col-md-6 col-lg-4"><article class="photo-card h-100"><a href="<?= baseUrl('photo/'.$photo['id']) ?>"><img class="photo-thumb" src="<?= baseUrl('images/uploads/'.e($photo['file_name'])) ?>" alt="<?= e($photo['title']) ?>"></a><div class="p-3"><div class="small text-secondary">By <?= e($photo['author']) ?></div><h2 class="h5 mt-1 mb-1"><a class="text-decoration-none text-dark" href="<?= baseUrl('photo/'.$photo['id']) ?>"><?= e($photo['title']) ?></a></h2><p class="text-secondary small mb-0"><?= e(mb_strimwidth($photo['description']??'',0,110,'…')) ?></p></div></article></div><?php endforeach; ?></div><?php endif; ?><script>document.querySelectorAll('[data-grid]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-grid]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const g=document.querySelector('#gallery');if(!g)return;g.className='row g-4 gallery-grid';const v=b.dataset.grid;document.querySelectorAll('.gallery-item').forEach(i=>i.className='gallery-item '+(v==='list'?'col-12':v==='4'?'col-md-6 col-lg-3':'col-md-6 col-lg-4'));}));</script>
